UPDATE basic_user
   SET role_id = #{roleId},
       updated_at = NOW(),
       updated_by = #{updatedBy}
 WHERE user_id = #{userId}

mapper.select:
SELECT u.id , u.user_id , u.created_at , u.created_by , u.updated_at , u.updated_by , u.user_nm , u.email , u.status , u.last_login_at , u.role_id , r.role_code FROM basic_user u JOIN basic_role r ON u.role_id = r.id
AND u.user_id = #{userId}
ORDER BY u.id LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM basic_user


        AND user_id = #{userId}
